import { QdrantClient } from "@qdrant/js-client-rest";

const client = new QdrantClient({ url: "http://localhost:6333" });
await client.createCollection("docs", { vectors: { size: 3, distance: "Cosine" } });
await client.upsert("docs", { points: [{ id: 1, vector: [0.1, 0.9, 0.0], payload: { lang: "en" } }] });
console.log(await client.query("docs", { query: [0.1, 0.8, 0.1], limit: 1 }));
